<?php use App\Support\Security;use App\Support\View;$base='/admin/tournaments/'.(int)$tournament['id'].'/operation';$token=View::e(Security::csrfToken());$eligible=function(int $match,int $team)use($candidates){return $candidates[$match][$team]??[];};$upcoming=array_values(array_filter($matches,fn($m)=>in_array($m['status'],['scheduled','confirmed'],true)));$completed=array_values(array_filter($matches,fn($m)=>in_array($m['status'],['homologated','awaiting_homologation'],true)));$goals=array_sum(array_map(fn($m)=>(int)($m['home_score']??0)+(int)($m['away_score']??0),$completed));?>
<main class="content operation-page">
