  <section class="tournament-overview"><header class="tournament-hero"><div><span class="eyebrow">Central do campeonato</span><h1><?=View::e($tournament['name'])?></h1><p class="muted">Temporada <?=View::e($tournament['season']??'Atual')?> · <?=View::e($tournament['status']??'Ativo')?> · <?=count($stages)?> fases configuradas</p></div><div class="quick-actions"><a class="button" href="#partidas">Abrir partidas</a><a class="button ghost" href="/admin/tournaments/<?=$tournament['id']?>/configuration">Configurar</a></div></header><div class="overview-grid"><article class="metric-card"><span>Equipes</span><strong><?=count($teams)?></strong><small>Inscritas</small></article><article class="metric-card"><span>Atletas</span><strong><?=count($athletes)?></strong><small>Vínculos ativos</small></article><article class="metric-card"><span>Partidas</span><strong><?=count($matches)?></strong><small><?=count($completed)?> concluídas</small></article><article class="metric-card"><span>Gols</span><strong><?=$goals?></strong><small>Registrados</small></article><article class="metric-card"><span>Pendências</span><strong><?=$counts['pending']?></strong><small>Inscrições</small></article><article class="metric-card"><span>Suspensões</span><strong><?=$counts['suspensions']?></strong><small>Ativas</small></article></div></section>
  <nav class="operation-nav" aria-label="Atalhos do campeonato"><a href="#equipes">Equipes</a><a href="#atletas">Atletas</a><a href="#comissao">Comissão</a><a href="#inscricoes">Inscrições</a><a href="#grupos">Grupos e tabela</a><a href="#partidas">Partidas</a><a href="#homologacoes">Homologações</a><a href="#sumulas">Súmulas</a></nav>
  <section class="stats" aria-label="Resumo operacional"><article class="stat"><strong><?=count($teams)?></strong><span>Equipes inscritas</span></article><article class="stat"><strong><?=count($athletes)?></strong><span>Atletas vinculados</span></article><article class="stat"><strong><?=$counts['future']?></strong><span>Partidas futuras</span></article><article class="stat"><strong><?=$counts['pending']?></strong><span>Pendências de inscrição</span></article><article class="stat"><strong><?=$counts['suspensions']?></strong><span>Suspensões ativas</span></article></section>

  <section class="panel" id="equipes"><div class="panel-head"><div><span class="eyebrow">1. Cadastro</span><h2>Equipes</h2></div><span class="muted">Cada equipe já entra no campeonato atual.</span></div>
    <form method="post" action="<?=$base?>/teams" class="form-grid"><input type="hidden" name="_csrf" value="<?=$token?>"><label>Nome completo<input required name="name" maxlength="160" autocomplete="organization"></label><label>Nome curto<input name="short_name" maxlength="40"></label><label>Sigla<input name="acronym" maxlength="12"></label><label>Slug público<input name="slug" maxlength="180" placeholder="ex.: estrela-do-norte"></label><label>Categoria<select name="category_id"><option value="">Sem categoria específica</option><?php foreach($categories as $c):?><option value="<?=$c['id']?>"><?=View::e($c['name'])?></option><?php endforeach;?></select></label><label>Cidade<input name="city" maxlength="120"></label><label>Cor principal<input name="primary_color" type="color" value="#1261a0"></label><label>Cor secundária<input name="secondary_color" type="color" value="#0f7b52"></label><label>Responsável<input name="contact_name" maxlength="160"></label><label>Telefone<input name="contact_phone" maxlength="40" inputmode="tel"></label><label>E-mail<input name="contact_email" type="email"></label><button class="button primary">Cadastrar equipe</button></form>
    <div class="table-wrap"><table><thead><tr><th>Equipe</th><th>Categoria</th><th>Cidade</th><th>Situação</th><th>Ação</th></tr></thead><tbody><?php foreach($teams as $team):?><tr><td><strong><?=View::e($team['name'])?></strong><br><small><?=View::e($team['acronym']??$team['short_name']??'')?></small></td><td><?=View::e($team['category_id']??'—')?></td><td><?=View::e($team['city']??'—')?></td><td><?=View::e($team['status'])?></td><td><form method="post" action="<?=$base?>/teams/status" class="inline-form"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="team_id" value="<?=$team['id']?>"><select name="action"><option value="deactivate">Inativar</option><option value="activate">Ativar</option><option value="delete">Excluir</option><option value="restore">Restaurar</option></select><button class="link" data-confirm="Confirmar alteração da equipe?">Aplicar</button></form></td></tr><?php endforeach;?><?php if(!$teams):?><tr><td colspan="5" class="empty">Nenhuma equipe inscrita neste campeonato.</td></tr><?php endif;?></tbody></table></div>
  </section>

  <section class="panel" id="atletas"><div class="panel-head"><div><span class="eyebrow">2. Elenco</span><h2>Atletas</h2></div><span class="muted">O vínculo com a equipe é criado junto ao cadastro.</span></div>
    <form method="post" action="<?=$base?>/athletes" class="form-grid"><input type="hidden" name="_csrf" value="<?=$token?>"><label>Nome completo<input required name="full_name" maxlength="180"></label><label>Nome esportivo<input name="public_name" maxlength="120"></label><label>Equipe<select required name="team_id"><option value="">Selecione</option><?php foreach($teams as $team):if($team['status']==='active'):?><option value="<?=$team['id']?>"><?=View::e($team['name'])?></option><?php endif;endforeach;?></select></label><label>Data de nascimento<input name="birth_date" type="date"></label><label>Posição<select name="position"><option value="">Selecione</option><option>Goleiro</option><option>Defensor</option><option>Meio-campista</option><option>Atacante</option></select></label><label>Número preferencial<input name="preferred_number" type="number" min="1" max="99"></label><label>Pé dominante<select name="dominant_foot"><option value="">Selecione</option><option>Direito</option><option>Esquerdo</option><option>Ambidestro</option></select></label><label>Telefone<input name="phone" inputmode="tel"></label><label>E-mail<input name="email" type="email"></label><label>Responsável legal (menores)<input name="guardian_name" maxlength="180"></label><label>Parentesco<select name="guardian_relationship"><option value="Responsável">Responsável</option><option value="Mãe">Mãe</option><option value="Pai">Pai</option><option value="Tutor">Tutor</option></select></label><label>Telefone do responsável<input name="guardian_phone" inputmode="tel"></label><label class="checkbox-label"><input type="checkbox" name="guardian_authorized" value="1"> Autorização de inscrição confirmada</label><button class="button primary">Cadastrar atleta</button></form>
    <div class="table-wrap"><table><thead><tr><th>Atleta</th><th>Equipe</th><th>Posição</th><th>Número</th><th>Situação</th></tr></thead><tbody><?php foreach($athletes as $athlete):?><tr><td><?=View::e($athlete['public_name']?:$athlete['full_name'])?></td><td><?=View::e($athlete['team_name'])?></td><td><?=View::e($athlete['primary_position']??'—')?></td><td><?=View::e($athlete['preferred_number']??'—')?></td><td><?=View::e($athlete['status'])?></td></tr><?php endforeach;?><?php if(!$athletes):?><tr><td colspan="5" class="empty">Cadastre atletas após criar uma equipe.</td></tr><?php endif;?></tbody></table></div>
  </section>

  <section class="panel" id="comissao"><div class="panel-head"><div><span class="eyebrow">2. Comissão</span><h2>Comissão técnica</h2></div><span class="muted">Vínculo ativo para o campeonato e equipe selecionados.</span></div><form method="post" action="<?=$base?>/staff" class="form-grid"><input type="hidden" name="_csrf" value="<?=$token?>"><label>Nome completo<input required name="full_name"></label><label>Equipe<select required name="team_id"><option value="">Selecione</option><?php foreach($teams as $team):if($team['status']==='active'):?><option value="<?=$team['id']?>"><?=View::e($team['name'])?></option><?php endif;endforeach;?></select></label><label>Função<select required name="role"><option value="">Selecione</option><option>Treinador</option><option>Auxiliar</option><option>Preparador físico</option><option>Fisioterapeuta</option><option>Médico</option><option>Massagista</option><option>Dirigente</option><option>Responsável da equipe</option><option>Outro</option></select></label><label>Telefone<input name="phone" inputmode="tel"></label><label>E-mail<input name="email" type="email"></label><button class="button primary">Cadastrar integrante</button></form><div class="table-wrap"><table><thead><tr><th>Nome</th><th>Equipe</th><th>Função</th><th>Situação</th></tr></thead><tbody><?php foreach($staff as $member):?><tr><td><?=View::e($member['full_name'])?></td><td><?=View::e($member['team_name'])?></td><td><?=View::e($member['role'])?></td><td><?=View::e($member['status'])?></td></tr><?php endforeach;?><?php if(!$staff):?><tr><td class="empty" colspan="4">Nenhum integrante de comissão cadastrado.</td></tr><?php endif;?></tbody></table></div></section>

  <section class="panel" id="inscricoes"><div class="panel-head"><div><span class="eyebrow">3. Inscrições</span><h2>Central de inscrições</h2></div><span class="muted">Aprovação libera escalação.</span></div><form method="post" action="<?=$base?>/registrations" class="form-grid" data-team-filter><input type="hidden" name="_csrf" value="<?=$token?>"><label>Equipe<select required name="team_id" data-team-selector><option value="">Selecione</option><?php foreach($teams as $team):if($team['status']==='active'):?><option value="<?=$team['id']?>"><?=View::e($team['name'])?></option><?php endif;endforeach;?></select></label><label>Atleta cadastrado<select required name="person_id" data-team-options><option value="">Escolha primeiro a equipe</option><?php foreach($athletes as $a):?><option value="<?=$a['id']?>" data-team="<?=$a['team_id']?>" hidden><?=View::e($a['full_name'])?></option><?php endforeach;?></select></label><label>Número para súmula<input name="shirt_number" maxlength="3" inputmode="numeric"></label><button class="button primary">Criar inscrição</button></form><div class="table-wrap"><table><thead><tr><th>Atleta</th><th>Equipe</th><th>Situação</th><th>Decisão</th></tr></thead><tbody><?php foreach($registrations as $r):?><tr><td><?=View::e($r['full_name'])?></td><td><?=View::e($r['team_name'])?></td><td><?=View::e($r['status'])?><?=!empty($r['rejection_reason'])?'<br><small>'.View::e($r['rejection_reason']).'</small>':''?></td><td><form method="post" action="<?=$base?>/registrations/review" class="inline-form"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="registration_id" value="<?=$r['id']?>"><select name="status"><option value="submitted">Enviar</option><option value="under_review">Em análise</option><option value="pending">Solicitar correção</option><option value="approved">Aprovar</option><option value="rejected">Rejeitar</option><option value="suspended">Suspender</option><option value="cancelled">Cancelar</option></select><input name="reason" placeholder="Motivo quando necessário"><button class="link">Salvar</button></form></td></tr><?php endforeach;?><?php if(!$registrations):?><tr><td colspan="4" class="empty">Nenhuma inscrição criada.</td></tr><?php endif;?></tbody></table></div></section>

  <section class="panel" id="grupos"><div class="panel-head"><div><span class="eyebrow">4. Competição</span><h2>Grupos e geração da tabela</h2></div><span class="muted">Após gerar partidas, distribuição fica bloqueada.</span></div><form method="post" action="<?=$base?>/groups" class="form-grid"><input type="hidden" name="_csrf" value="<?=$token?>"><label>Fase<select required name="stage_id"><option value="">Selecione</option><?php foreach($stages as $s):?><option value="<?=$s['id']?>"><?=View::e($s['name'])?></option><?php endforeach;?></select></label><label>Nome do grupo<input required name="name" placeholder="Grupo A"></label><label>Código<input required name="code" maxlength="8" placeholder="A"></label><label>Vagas<input required name="max_teams" value="5" type="number" min="2" max="64"></label><button class="button primary">Criar grupo</button></form><?php foreach($groups as $g):?><article class="subpanel"><div class="panel-head"><h3><?=View::e($g['name'])?> <small class="muted">(<?=count($g['teams'])?>/<?=$g['max_teams']?>)</small></h3><span><?=View::e($g['status'])?></span></div><ul class="simple-list"><?php foreach($g['teams'] as $team):?><li><?=View::e($team['name'])?><form method="post" action="<?=$base?>/groups/remove"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="group_id" value="<?=$g['id']?>"><input type="hidden" name="team_id" value="<?=$team['id']?>"><button class="link danger">Retirar</button></form></li><?php endforeach;?></ul><div class="operation-actions"><form method="post" action="<?=$base?>/groups/assign" class="inline-form"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="group_id" value="<?=$g['id']?>"><select required name="team_id"><option value="">Adicionar equipe</option><?php foreach($teams as $team):if($team['status']==='active'):?><option value="<?=$team['id']?>"><?=View::e($team['name'])?></option><?php endif;endforeach;?></select><button class="button">Adicionar</button></form><form method="post" action="<?=$base?>/schedule" class="inline-form"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="group_id" value="<?=$g['id']?>"><label>Primeiro jogo<input required name="start_at" type="datetime-local"></label><button class="button">Gerar e publicar tabela</button></form></div></article><?php endforeach;?><?php if(!$groups):?><p class="empty">Crie os grupos antes de distribuir as equipes.</p><?php endif;?></section>

  <section class="panel" id="partidas"><div class="panel-head"><div><span class="eyebrow">5. Central da partida</span><h2>Partidas, escalações e eventos</h2></div><form method="post" action="<?=$base?>/knockout"><input type="hidden" name="_csrf" value="<?=$token?>"><button class="button">Gerar mata-mata</button></form></div><div class="table-wrap"><table><thead><tr><th>Partida</th><th>Fase / rodada</th><th>Data</th><th>Placar</th><th>Situação</th><th>Operar</th></tr></thead><tbody><?php foreach($matches as $m):?><tr><td><strong><?=View::e($m['home_name'])?></strong> × <strong><?=View::e($m['away_name'])?></strong></td><td><?=View::e($m['stage_name']??'—')?><br><small><?=View::e($m['round_name']??'')?></small></td><td><?=View::e($m['scheduled_at']??'A definir')?></td><td><?=$m['home_score']??0?> × <?=$m['away_score']??0?></td><td><?=View::e($m['status'])?></td><td><details><summary>Abrir central</summary><div class="match-center"><h3><?=View::e($m['home_name'])?> <?=$m['home_score']??0?> × <?=$m['away_score']??0?> <?=View::e($m['away_name'])?></h3><div class="lineup-grid"><?php foreach([(int)$m['home_team_id']=>$m['home_name'],(int)$m['away_team_id']=>$m['away_name']] as $teamId=>$teamName):?><form method="post" action="<?=$base?>/lineups"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="match_id" value="<?=$m['id']?>"><input type="hidden" name="team_id" value="<?=$teamId?>"><h4>Escalação: <?=View::e($teamName)?></h4><p class="muted">Marque titulares, reservas, capitão e goleiro.</p><div class="lineup-list"><?php foreach($eligible((int)$m['id'],$teamId) as $player):?><label class="lineup-row"><input type="checkbox" name="players[<?=$player['id']?>][selected]"><span><?=View::e($player['full_name'])?></span><select name="players[<?=$player['id']?>][role]"><option value="starter">Titular</option><option value="substitute">Reserva</option></select><input name="players[<?=$player['id']?>][number]" value="<?=View::e($player['shirt_number']??'')?>" aria-label="Número de <?=View::e($player['full_name'])?>"><span><input type="checkbox" name="players[<?=$player['id']?>][captain]">Cap.</span><span><input type="checkbox" name="players[<?=$player['id']?>][goalkeeper]">Gol.</span></label><?php endforeach;?><?php if(!$eligible((int)$m['id'],$teamId)):?><p class="empty">Sem atletas aprovados nesta equipe.</p><?php endif;?></div><button class="button">Salvar escalação</button></form><?php endforeach;?></div><form method="post" action="<?=$base?>/events" class="form-grid event-form"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="match_id" value="<?=$m['id']?>"><label>Equipe<select name="team_id"><option value="<?=$m['home_team_id']?>"><?=View::e($m['home_name'])?></option><option value="<?=$m['away_team_id']?>"><?=View::e($m['away_name'])?></option></select></label><label>Atleta<select name="person_id"><option value="">Sem atleta</option><?php foreach(array_merge($eligible((int)$m['id'],(int)$m['home_team_id']),$eligible((int)$m['id'],(int)$m['away_team_id'])) as $player):?><option value="<?=$player['id']?>"><?=View::e($player['full_name'])?></option><?php endforeach;?></select></label><label>Assistente (quando houver)<select name="assist_person_id"><option value="">Nenhum</option><?php foreach(array_merge($eligible((int)$m['id'],(int)$m['home_team_id']),$eligible((int)$m['id'],(int)$m['away_team_id'])) as $player):?><option value="<?=$player['id']?>"><?=View::e($player['full_name'])?></option><?php endforeach;?></select></label><label>Evento<select name="event_type"><option value="start">Iniciar partida</option><option value="halftime">Iniciar intervalo</option><option value="second_half">Iniciar segundo tempo</option><option value="goal">Gol</option><option value="own_goal">Gol contra</option><option value="assist">Assistência</option><option value="yellow">Cartão amarelo</option><option value="second_yellow">Segundo amarelo</option><option value="red">Cartão vermelho</option><option value="substitution">Substituição</option><option value="stoppage">Acréscimo</option><option value="incident">Ocorrência</option><option value="end">Encerrar tempo</option></select></label><label>Período<select name="period"><option value="first">1º tempo</option><option value="second">2º tempo</option></select></label><label>Minuto<input name="minute" type="number" min="0" max="180"></label><button class="button primary">Registrar evento</button></form><div class="operation-actions"><form method="post" action="<?=$base?>/finish"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="match_id" value="<?=$m['id']?>"><button class="button">Finalizar e enviar para homologação</button></form><a class="button" href="/admin/tournaments/<?=$tournament['id']?>/matches/<?=$m['id']?>/report">Revisar súmula</a></div></div></details></td></tr><?php endforeach;?><?php if(!$matches):?><tr><td colspan="6" class="empty">Gere a tabela de um grupo para criar partidas.</td></tr><?php endif;?></tbody></table></div></section>

  <section class="panel" id="homologacoes"><div class="panel-head"><div><span class="eyebrow">6. Revisão</span><h2>Homologações</h2></div><span class="muted">Ação recalcula classificação e gera PDF privado.</span></div><div class="table-wrap"><table><thead><tr><th>Partida</th><th>Placar</th><th>Status</th><th>Ação</th></tr></thead><tbody><?php foreach($matches as $m):if(in_array($m['status'],['awaiting_homologation','rectified','homologated'],true)):?><tr><td><?=View::e($m['home_name'])?> × <?=View::e($m['away_name'])?></td><td><?=$m['home_score']??0?> × <?=$m['away_score']??0?></td><td><?=View::e($m['status'])?></td><td><?php if($m['status']!=='homologated'):?><form method="post" action="<?=$base?>/homologate" class="inline-form" data-confirm="Homologar resultado e atualizar classificação?"><input type="hidden" name="_csrf" value="<?=$token?>"><input type="hidden" name="match_id" value="<?=$m['id']?>"><button class="button">Homologar</button></form><?php endif;?></td></tr><?php endif;endforeach;?></tbody></table></div></section>
  <section class="panel" id="sumulas"><span class="eyebrow">7. Documentação</span><h2>Súmulas</h2><p class="muted">A visualização HTML serve para revisão; o PDF só fica disponível após homologação.</p><div class="simple-list"><?php foreach($matches as $m):if($m['report_pdf_path']):?><div><a class="link" href="/admin/tournaments/<?=$tournament['id']?>/matches/<?=$m['id']?>/report"><?=View::e($m['home_name'])?> × <?=View::e($m['away_name'])?> · visualizar</a> <a class="link" href="/admin/tournaments/<?=$tournament['id']?>/matches/<?=$m['id']?>/report.pdf">Baixar PDF</a></div><?php endif;endforeach;?></div></section>
